import math


def mean_code(text):
    chars = [ord(c) for c in text if not c.isspace()]
    return sum(chars) / max(len(chars), 1)


def score(program):
    size = math.log(1 + len(program)) / 10
    tone = mean_code(program) / 128
    return max(0.0, min(1.0, (size + tone) / 2))

